-- UT Software — Tyre entry enum-assignment fix post-deployment verification
-- STRICTLY READ ONLY: catalog inspection and SELECT queries only.

with target as (
 select to_regprocedure('public.save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)') oid
), definition as (
 select oid,coalesce(pg_get_functiondef(oid),'') body from target
), checks(check_name,status,details,blocking) as (
 values
 ('TARGET_RPC_EXISTS',case when (select oid from target) is not null then 'PASS' else 'FAIL' end,'Corrected save_vehicle_tyre_entry identity must exist.',true),
 ('CURRENT_STATUS_ENUM_SAFE',case when lower((select body from definition)) ~ '''fitted_again''::(public\.)?tyre_asset_status' and lower((select body from definition)) ~ '''fitted''::(public\.)?tyre_asset_status' then 'PASS' else 'FAIL' end,'current_status CASE explicitly returns tyre_asset_status.',true),
 ('FIT_EVENT_ENUM_SAFE',case when lower((select body from definition)) ~ '''fitted_again''::(public\.)?tyre_event_type' and lower((select body from definition)) ~ '''fitted''::(public\.)?tyre_event_type' then 'PASS' else 'FAIL' end,'Fitted/fitted_again event CASE explicitly returns tyre_event_type.',true),
 ('SERVICE_EVENT_ENUM_SAFE',case when lower((select body from definition)) ~ '''retread''::(public\.)?tyre_event_type' and lower((select body from definition)) ~ '''repair''::(public\.)?tyre_event_type' then 'PASS' else 'FAIL' end,'Repair/retread event CASE explicitly returns tyre_event_type.',true),
 ('REMOVAL_ENUM_SAFE',case when lower((select body from definition)) ~ 'v_old_status\s*:=\s*''removed''::(public\.)?tyre_asset_status' and lower((select body from definition)) ~ '''removed''::(public\.)?tyre_event_type' then 'PASS' else 'FAIL' end,'Removal status/event assignments are explicitly enum-safe.',true),
 ('TYPED_PARAMETER_ASSIGNMENTS',case when lower((select body from definition)) ~ 'p_source_type\s+(public\.)?tyre_source_type' and lower((select body from definition)) ~ 'p_work_type\s+(public\.)?tyre_work_type' and lower((select body from definition)) ~ 'v_work\s+(public\.)?tyre_work_type' and lower((select body from definition)) ~ 'resulting_status\s*=\s*v_old_status' then 'PASS' else 'FAIL' end,'Source, work and resulting-status assignments retain typed values.',true),
 ('RPC_SECURITY',case when exists(select 1 from pg_proc p join target t on t.oid=p.oid where p.prosecdef and coalesce(array_to_string(p.proconfig,','),'') like '%search_path=public, pg_temp%') then 'PASS' else 'FAIL' end,'RPC remains SECURITY DEFINER with locked search_path.',true),
 ('RPC_GRANTS',case when has_function_privilege('authenticated',(select oid from target),'EXECUTE') and not has_function_privilege('anon',(select oid from target),'EXECUTE') then 'PASS' else 'FAIL' end,'Authenticated execute preserved; anon blocked.',true),
 ('TENANT_VALIDATION_PRESERVED',case when lower((select body from definition)) like '%ut_tyre_authorize_adda%' and lower((select body from definition)) ~ 'id\s*=\s*p_vehicle_id\s+and\s+adda_id\s*=\s*p_adda_id' and lower((select body from definition)) like '%tyre_source_shop_mismatch%' then 'PASS' else 'FAIL' end,'Adda, Vehicle and source-shop validation remain present.',true),
 ('ATOMIC_HISTORY_PRESERVED',case when lower((select body from definition)) like '%for update%' and lower((select body from definition)) ~ 'removed_date\s*=\s*p_entry_date' and lower((select body from definition)) ~ 'insert\s+into\s+public\.tyre_fitments' and lower((select body from definition)) ~ 'insert\s+into\s+public\.tyre_asset_events' then 'PASS' else 'FAIL' end,'Locking and append/close history remain present.',true),
 ('ASSET_CURRENT_STATE_INTEGRITY',case when not exists(select 1 from public.tyre_assets where (current_status in('fitted','fitted_again') and (current_vehicle_id is null or current_position_id is null)) or (current_status not in('fitted','fitted_again') and (current_vehicle_id is not null or current_position_id is not null))) then 'PASS' else 'FAIL' end,'Asset current status/location invariants remain valid.',true),
 ('OPEN_FITMENT_UNIQUENESS',case when not exists(select 1 from public.tyre_fitments where removed_date is null group by tyre_asset_id having count(*)>1) and not exists(select 1 from public.tyre_fitments where removed_date is null group by vehicle_position_id having count(*)>1) then 'PASS' else 'FAIL' end,'One open fitment per asset/position remains valid.',true),
 ('OPEN_FITMENT_ASSET_MATCH',case when not exists(select 1 from public.tyre_fitments f join public.tyre_assets a on a.id=f.tyre_asset_id where f.removed_date is null and (a.current_status not in('fitted','fitted_again') or a.current_vehicle_id is distinct from f.vehicle_id or a.current_position_id is distinct from f.vehicle_position_id)) then 'PASS' else 'FAIL' end,'Open fitments match asset current location.',true),
 ('NO_ORPHAN_TYRE_RELATIONS',case when not exists(select 1 from public.tyre_vehicle_entry_items i left join public.tyre_vehicle_entries e on e.id=i.tyre_vehicle_entry_id where e.id is null) and not exists(select 1 from public.tyre_fitments f left join public.tyre_assets a on a.id=f.tyre_asset_id left join public.tyre_vehicle_entries e on e.id=f.source_entry_id where a.id is null or e.id is null) and not exists(select 1 from public.tyre_asset_events e left join public.tyre_assets a on a.id=e.tyre_asset_id where a.id is null) then 'PASS' else 'FAIL' end,'No orphan Tyre history or entry rows.',true),
 ('ACCOUNTING_BOUNDARY',case when lower((select body from definition)) !~ 'cashbook|voucher|expense_items|oil_|workshop|payment' then 'PASS' else 'FAIL' end,'Corrected RPC contains no accounting or unrelated-module operation.',true),
 ('PROTECTION_TRIGGERS_UNCHANGED',case when (select count(*) from pg_trigger where not tgisinternal and tgname in('tyre_assets_protect','vehicle_tyre_positions_protect','tyre_vehicle_entries_protect','tyre_vehicle_entry_items_protect','tyre_fitments_protect','tyre_asset_events_protect'))=6 then 'PASS' else 'FAIL' end,'All six mutation guards remain installed.',true),
 ('TYRE_DATA_COUNTS','INFO',format('assets=%s; entries=%s; items=%s; fitments=%s; events=%s',(select count(*) from public.tyre_assets),(select count(*) from public.tyre_vehicle_entries),(select count(*) from public.tyre_vehicle_entry_items),(select count(*) from public.tyre_fitments),(select count(*) from public.tyre_asset_events)),false),
 ('FIX_SCOPE','INFO','Only one RPC definition and its execute grants were replaced; no business-data DML or accounting DDL.',false)
), combined as (
 select 'OVERALL_TYRE_ENTRY_ENUM_FIX_POST_VERIFY'::text check_name,case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details from checks
 union all select check_name,status,details from checks
)
select check_name,status,details from combined order by case when check_name='OVERALL_TYRE_ENTRY_ENUM_FIX_POST_VERIFY' then 0 else 1 end,check_name;
